#!/bin/sh
# Static validation of nftables commands generated by fwb_nft.
# Does not execute or install the firewall ruleset.
set -eu
[ "$#" -gt 0 ] || { echo 'Usage: check-nft-output.sh SCRIPT.fw ...' >&2; exit 2; }
for fw in "$@"; do
    [ -s "$fw" ] || { echo "Empty nft script: $fw" >&2; exit 1; }
    sh -n "$fw" || { echo "Invalid shell wrapper: $fw" >&2; exit 1; }
    awk '
    function fail(msg) { print FILENAME ":" NR ": " msg > "/dev/stderr"; bad=1 }
    # Reload must enter the atomic start path directly. Stopping first
    # removes active FWB protection before the replacement is ready.
    /^[[:space:]]*reload\)[[:space:]]*$/ { in_reload=1; reload_count++; next }
    in_reload && /^[[:space:]]*;;[[:space:]]*$/ { in_reload=0; next }
    in_reload && /^[[:space:]]*#/ { next }
    in_reload && /(stop_action|\$0[[:space:]]+stop|"\$0"[[:space:]]+stop)/ {
        fail("reload removes active firewall policy before replacement")
        next
    }
    in_reload && /"\$0"[[:space:]]+start/ { reload_starts++; next }
    /<<\047FWB_NFT_RULESET\047/ {
        if (active) fail("nested native nftables ruleset")
        active=1; opened++; next
    }
    /^FWB_NFT_RULESET[[:space:]]*$/ {
        if (!active) fail("unmatched native ruleset end")
        active=0; next
    }
    # No FWB operation may erase unrelated nftables rules or tables.
    /^[[:space:]]*(\$NFT[[:space:]]+)?flush[[:space:]]+ruleset([[:space:]]|$)/ {
        fail("global nftables flush forbidden: " $0); next
    }
    !active { next }
    /^[[:space:]]*$/ || /^[[:space:]]*#/ { next }
    {
        n=split($0, part, /[[:space:]]+/)
        if ($1=="flush" && $2=="ruleset") { fail("global ruleset flush forbidden"); next }
        if ($1!="add") { fail("non-native command inside nft heredoc: " $0); next }
        if ($2=="table" && n>=4) {
            family=part[3]; tab=part[4]
            if (tab !~ /^fwb_(filter|nat|mangle)$/) fail("unowned nft table: " tab)
            table[family " " tab]=1
            next
        }
        if ($2=="chain" && n>=5) {
            family=part[3]; tab=part[4]; chain=part[5]
            key=family " " tab " " chain
            if (!table[family " " tab]) fail("chain before table: " key)
            if (chains[key]) fail("duplicate chain: " key)
            chains[key]=1
            if (tab=="fwb_nat" && $0 !~ /type nat hook/) fail("NAT base chain missing nat hook: " key)
            if (tab=="fwb_mangle" && $0 !~ /type (filter|route) hook/) fail("mangle base chain missing hook: " key)
            next
        }
        # Named dynamic hashlimit sets are nftables objects, not rules.
        # They must belong to an existing FWB table and be declared once.
        if ($2=="set" && n>=6) {
            family=part[3]; tab=part[4]; setname=part[5]
            key=family " " tab " " setname
            if (tab !~ /^fwb_(filter|mangle)$/) fail("unowned nft set table: " tab)
            if (!table[family " " tab]) fail("set before table: " key)
            if (setname !~ /^fwb_[[:alnum:]_]+$/) fail("invalid FWB set name: " setname)
            if (sets[key]++) fail("duplicate set declaration: " key)
            if ($0 !~ /[[:space:]]\{[[:space:]]*type[[:space:]]+/ ||
                $0 !~ /;[[:space:]]*\}[[:space:]]*$/)
                fail("malformed named set declaration: " key)
            next
        }
        if ($2=="rule" && n>=6) {
            family=part[3]; tab=part[4]; chain=part[5]
            key=family " " tab " " chain
            if (tab !~ /^fwb_(filter|nat|mangle)$/) fail("unowned nft table referenced: " tab)
            if (!chains[key]) fail("rule references undefined chain: " key)
            if ($0 ~ /[io]ifname[[:space:]]+"[^"]*\+"/) fail("iptables-style interface wildcard: " $0)
            if ($0 ~ /[io]ifname[[:space:]]+"\*"/) fail("bare interface wildcard: " $0)
            if ($0 ~ /(^|[[:space:]])(--[[:alnum:]]+|-j|-m)([[:space:]]|$)/)
                fail("iptables option in native rule: " $0)
            if ($0 ~ /\$/) fail("unexpanded variable in native ruleset: " $0)
            rules++
            next
        }
        fail("unrecognized nft command: " $0)
    }
    END {
        if (reload_count!=1 || reload_starts!=1 || in_reload)
            fail("reload must invoke atomic start exactly once without stop")
        if (opened!=1 || active) fail("expected exactly one complete FWB_NFT_RULESET")
        if (rules<1) fail("native ruleset contains no rules")
        if (!bad) print "Native nftables structure OK: " FILENAME " (" rules " rules)"
        exit bad ? 1 : 0
    }' "$fw" || exit 1
done
